package dev.eugheist.ttmodern;
import net.minecraft.world.item.*;
import thaumcraft.api.aspects.*;
import thaumcraft.api.research.*;
final class IchorAudit {
 private static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT ichor: "+label);}
 private static ResearchItem sample(String key,String category){return new ResearchItem(key,category,new AspectList(),0,0,1,new ItemStack(Items.STICK)).setParents("prerequisite");}
 static void run(){
  var r=ResearchCategories.getResearch("ICHOR");check(r instanceof KamiResearch&&r.displayColumn==9&&r.displayRow==8&&r.isConcealed(),"original mastery research");var requirements=new java.util.HashSet<>(java.util.Arrays.asList(r.parentsHidden));check(requirements.size()==r.parentsHidden.length&&requirements.containsAll(java.util.List.of("ENCHANTER","INFUSED_POTIONS","CLEANSING_TALISMAN","INFUSION")),"mastery includes late addon and base dependencies without duplicates");check(!requirements.contains("ICHOR")&&!requirements.contains("DIMENSION_SHARDS")&&!requirements.contains("DARK_QUARTZ"),"KAMI self/clue/root excluded");check(dev.eugheist.tc4modern.ResearchProgress.requisites(requirements,r),"actual progression accepts full mastery");var missing=new java.util.HashSet<>(requirements);missing.remove("ENCHANTER");check(!dev.eugheist.tc4modern.ResearchProgress.requisites(missing,r)&&!dev.eugheist.tc4modern.ResearchProgress.requisites(java.util.Set.of(),r),"one missing study prevents unlock");
  check(KamiResearch.required(sample("ordinary","ARTIFICE")),"ordinary eligible");check(!KamiResearch.required(sample("lost","ARTIFICE").setLost())&&!KamiResearch.required(sample("virtual","ARTIFICE").setVirtual())&&!KamiResearch.required(sample("MINILITH_ALT","ARTIFICE"))&&!KamiResearch.required(sample("alternateKAMI","ARTIFICE"))&&!KamiResearch.required(sample("eldritch","ELDRITCH")),"lost/virtual/prefix/suffix/foreign category exceptions");check(!KamiResearch.required(sample("trigger","ARTIFICE").setItemTriggers(new ItemStack(Items.STICK)))&&!KamiResearch.required(sample("trigger","ARTIFICE").setAspectTriggers(Aspect.AIR))&&!KamiResearch.required(sample("trigger","ARTIFICE").setEntityTriggers("Cow")),"all three trigger exceptions");
  var merged=new KamiResearch("test",new AspectList(),0,0,1,new ItemStack(Items.STICK));merged.setParentsHidden("retained");merged.setPages(new ResearchPage("test"));check(java.util.Arrays.asList(merged.parentsHidden).contains("retained"),"explicit hidden parent retained");var auto=new KamiResearch("auto",new AspectList(),0,0,1,new ItemStack(Items.STICK));auto.setAutoUnlock();auto.setPages(new ResearchPage("test"));check(auto.parentsHidden.length==0&&!KamiResearch.required(merged),"auto clue skips mastery/other KAMI excluded");check(dev.eugheist.tc4modern.ResearchWarp.amount("ICHOR")==5,"original warp five");
  var recipe=dev.eugheist.tc4modern.InfusionItemRecipes.all().stream().filter(x->x.key().equals("ICHOR")).findFirst().orElseThrow();var parts=recipe.componentStacks();check(recipe.instability()==7&&recipe.aspects().size()==3&&recipe.aspects().getAmount(Aspect.MAN)==32&&recipe.aspects().getAmount(Aspect.LIGHT)==32&&recipe.aspects().getAmount(Aspect.SOUL)==64,"original instability/essentia");check(recipe.central().get()==Items.NETHER_STAR&&parts.size()==4&&parts.get(0).is(Items.DIAMOND)&&parts.get(1).is(KamiResources.item(KamiResources.Kind.ENDER_SHARD))&&parts.get(1).getCount()==1&&parts.get(2).is(Items.ENDER_EYE)&&parts.get(3).is(KamiResources.item(KamiResources.Kind.NETHER_SHARD))&&parts.get(3).getCount()==1,"original central and four single components, as the matrix consumes them");var central=new ItemStack(Items.NETHER_STAR);check(dev.eugheist.tc4modern.InfusionItemRecipes.match(parts,central,java.util.Set.of("ICHOR"))==recipe&&dev.eugheist.tc4modern.InfusionItemRecipes.match(parts,central,java.util.Set.of())==null,"actual infusion match and research gate");var singles=parts.stream().map(s->s.copyWithCount(1)).toList();check(dev.eugheist.tc4modern.InfusionItemRecipes.match(singles,central,java.util.Set.of("ICHOR"))==recipe,"original count-insensitive matching retained");var output=recipe.outputStack(central);check(output.is(KamiResources.item(KamiResources.Kind.ICHOR))&&output.getCount()==8,"native eight ichor output");output.setCount(1);check(recipe.outputStack(central).getCount()==8,"output independent");parts.get(1).setCount(8);check(recipe.componentStacks().get(1).getCount()==1,"preview stacks independent");
  System.out.println("TT ICHOR AUDIT: ALL PASS (mastery dependencies/exclusions/merge/auto,actual progression rejection,warp5,original infusion/cost/8output,count matching quirk)");
 }
}
